#!/usr/bin/env node
// NEW correction to preparation-only archive adapter: preserve the actual unknown-tool encoding.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';
const R=path.dirname(fileURLToPath(import.meta.url));
const h=b=>crypto.createHash('sha256').update(b).digest('hex');
const read=r=>fs.readFileSync(path.join(R,r));
const put=(r,b)=>fs.writeFileSync(path.join(R,r),b,{flag:'wx'});
const ser=o=>Buffer.from(JSON.stringify(o,null,2)+'\n');
const oldBytes=read('pack-032-evidence.mjs'),oldControlBytes=read('archive-032-control.json');
if(h(oldBytes)!=='baa2bd914758868580a38f0af3aab9199352ea705278fa1e697091928c4369c5'||h(oldControlBytes)!=='ff4204ffd9a5963746289f4fa0bd4951e98ff9ae3de92be0c0e44faabe54ce8e')throw new Error('Prepared predecessor changed');
const chat=JSON.parse(read('native-public/0-1-20/chat/session-evidence.json'));
if(chat.modelToolEventCount!=='UNKNOWN_NOT_EXPOSED')throw new Error('Actual pureChat unknown encoding changed');
const original=JSON.parse(oldControlBytes);
const rootFiles=['archive-032-control-r2.json','build-pack-032-native-logic-r2.mjs','packer-provenance/native-ui-0-1-20/preparation-control-r2.json','verify-lossless-032-dotnet.ps1'];
let source=oldBytes.toString('utf8');
source=source.replace(/const ROOT_FILES=.*?;\r?\n/,'const ROOT_FILES='+JSON.stringify(rootFiles)+';\n');
source=source.replaceAll("'archive-032-control.json'","'archive-032-control-r2.json'").replaceAll('archive-032-control.json scoped','archive-032-control-r2.json scoped');
if(!source.includes("chat.modelToolEventCount==='UNKNOWN'"))throw new Error('Unknown encoding anchor missing');
source=source.replace("chat.modelToolEventCount==='UNKNOWN'","chat.modelToolEventCount==='UNKNOWN_NOT_EXPOSED'");
put('pack-032-evidence-r2.mjs',Buffer.from(source));
const prep=JSON.parse(read('packer-provenance/native-ui-0-1-20/preparation-control.json'));
prep.recordedAt=new Date().toISOString();
prep.preparationProtocolCorrection={predecessorPackerSha256:h(oldBytes),predecessorControlSha256:h(oldControlBytes),actualReadOnlySchemaObservation:'737804',actualChatModelToolEncoding:'UNKNOWN_NOT_EXPOSED',incorrectDraftPredicate:'UNKNOWN',initialDraftNotExecutedAsDryRunOrPack:true,noSemanticOrCriteriaChange:true,noOriginalChanged:true,initialDraftRetainedPrivately:true};
prep.currentPackerSha256=h(read('pack-032-evidence-r2.mjs'));
put('packer-provenance/native-ui-0-1-20/preparation-control-r2.json',ser(prep));
const control={...original,sourceAllowlist:{rootFiles,rootDirectories:original.sourceAllowlist.rootDirectories},pinnedFinalEvidenceSha256:{...Object.fromEntries(Object.entries(original.pinnedFinalEvidenceSha256).filter(([r])=>r.startsWith('native-public/0-1-20/')))},preparationProtocolCorrection:prep.preparationProtocolCorrection};
for(const r of rootFiles.filter(r=>r!=='archive-032-control-r2.json'))control.pinnedFinalEvidenceSha256[r]=h(read(r));
put('archive-032-control-r2.json',ser(control));
console.log(JSON.stringify({phase:'NEW_PREPARATION_ONLY_PROTOCOL_ADAPTER',packerSha256:h(read('pack-032-evidence-r2.mjs')),controlSha256:h(read('archive-032-control-r2.json')),rootFiles,noRepoWrite:true,noPackOrGrade:true},null,2));

param(
  [Parameter(Mandatory=$true)][string]$Target,
  [Parameter(Mandatory=$true)][string]$ReviewerRoot
)
$ErrorActionPreference = 'Stop'
$targetRoot = [IO.Path]::GetFullPath($Target)
$reviewRoot = [IO.Path]::GetFullPath($ReviewerRoot)
$expectedTarget = [IO.Path]::GetFullPath((Join-Path $reviewRoot '../develop/docs/runbook/evidence/html-guide-kit/pr3-reviewer/native-032-scoped'))
if ($targetRoot -cne $expectedTarget) { throw 'Only the authorized new native-032-scoped archive may be verified.' }
function Get-RawSha([byte[]]$Bytes) {
  $algorithm = [Security.Cryptography.SHA256]::Create()
  try { return [BitConverter]::ToString($algorithm.ComputeHash($Bytes)).Replace('-','').ToLowerInvariant() }
  finally { $algorithm.Dispose() }
}
function Get-OwnedPath([string]$Base,[string]$Relative) {
  if ([IO.Path]::IsPathRooted($Relative) -or $Relative.Contains('\') -or $Relative -match '(^|/)\.{1,2}(/|$)' -or $Relative -match '(^/|//$|/$)') { throw 'Invalid archive relative path.' }
  $full = [IO.Path]::GetFullPath((Join-Path $Base $Relative))
  if (-not $full.StartsWith($Base.TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) { throw 'Archive path escapes its root.' }
  $walk = $Base
  foreach ($part in $Relative.Split('/')) {
    if (-not $part) { throw 'Empty archive path component.' }
    $walk = Join-Path $walk $part
    if (([IO.File]::GetAttributes($walk) -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Reparse-linked archive evidence is forbidden.' }
  }
  return $full
}
function Read-JsonBytes([string]$File) { return ([Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($File)) | ConvertFrom-Json -Depth 100) }
$index = Read-JsonBytes (Get-OwnedPath $targetRoot 'index.json')
if ($index.kind -ne 'lossless-reviewer-evidence-index' -or $index.schemaVersion -ne 1) { throw 'Unsupported archive index.' }
if ($index.actualAccounting.distinctRealUuidCount -ne 3 -or $index.actualAccounting.rawInputFileCount -ne 7) { throw 'Actual source accounting mismatch.' }
$identityBytes = [IO.File]::ReadAllBytes((Get-OwnedPath $targetRoot 'identities.json'))
if ((Get-RawSha $identityBytes) -cne $index.identityEvidenceSha256) { throw 'Identity hash mismatch.' }
$identities = [Text.Encoding]::UTF8.GetString($identityBytes) | ConvertFrom-Json -Depth 100
if ($identities.runIdentities.Count -ne 3 -or @($identities.runIdentities | Where-Object { $_.source.canonicalSha -cne '7e3deb8fb1d9960ede37ea96a714b1e34652a751' }).Count) { throw 'Three exact native source7e3d identities required.' }
$mapped = [Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
foreach ($row in $index.files) { if ($mapped.ContainsKey($row.relativeOriginalPath)) { throw 'Duplicate index entry.' }; $mapped.Add($row.relativeOriginalPath,$row) }
if ($mapped.Count -ne $index.fileCount) { throw 'Index count mismatch.' }
$seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
$totalBytes = [long]0
foreach ($packet in $index.packets) {
  $packetBytes = [IO.File]::ReadAllBytes((Get-OwnedPath $targetRoot $packet.file))
  if ($packetBytes.Length -gt 2097151 -or $packetBytes.Length -ne $packet.bytes -or (Get-RawSha $packetBytes) -cne $packet.sha256) { throw 'Packet size/hash mismatch or 2MiB limit exceeded.' }
  $document = [Text.Encoding]::UTF8.GetString($packetBytes) | ConvertFrom-Json -Depth 100
  if ($document.entries.Count -ne $packet.fileCount) { throw 'Packet entry count mismatch.' }
  $position = 0
  foreach ($entry in $document.entries) {
    if (-not $seen.Add($entry.relativeOriginalPath) -or -not $mapped.ContainsKey($entry.relativeOriginalPath)) { throw 'Duplicate or unmapped original file.' }
    $row = $mapped[$entry.relativeOriginalPath]
    if ($row.packet -cne $packet.file -or $row.entryIndex -ne $position -or $row.sha256 -cne $entry.sha256 -or $row.bytes -ne $entry.bytes -or $row.encoding -cne $entry.encoding -or $row.originalAbsolutePath -cne $entry.originalAbsolutePath) { throw 'Index packet mapping mismatch.' }
    if ($entry.encoding -eq 'utf8') { $restored = [Text.Encoding]::UTF8.GetBytes([string]$entry.content) }
    elseif ($entry.encoding -eq 'base64') { $restored = [Convert]::FromBase64String([string]$entry.content) }
    else { throw 'Unsupported original byte encoding.' }
    if ($restored.Length -ne $entry.bytes -or (Get-RawSha $restored) -cne $entry.sha256) { throw 'Restored original byte length/hash mismatch.' }
    $original = [IO.File]::ReadAllBytes((Get-OwnedPath $reviewRoot $entry.relativeOriginalPath))
    if ($original.Length -ne $restored.Length -or (Get-RawSha $original) -cne (Get-RawSha $restored)) { throw 'Original comparison mismatch.' }
    for ($i=0;$i -lt $original.Length;$i++) { if ($original[$i] -ne $restored[$i]) { throw 'Exact original byte mismatch.' } }
    $totalBytes += $restored.Length
    $position++
  }
}
if ($seen.Count -ne $index.fileCount -or $totalBytes -ne $index.originalBytes) { throw 'Complete byte restoration counts mismatch.' }
[string[]]$ordered = @($mapped.Keys)
[Array]::Sort($ordered,[StringComparer]::Ordinal)
$inventory = [Text.StringBuilder]::new()
foreach ($relative in $ordered) {
  $row = $mapped[$relative]
  [void]$inventory.Append($relative).Append([char]0).Append($row.sha256).Append([char]0).Append([string]$row.bytes).Append([char]10)
}
$inventorySha = Get-RawSha ([Text.Encoding]::UTF8.GetBytes($inventory.ToString()))
if ($inventorySha -cne $index.sourceInventorySha256) { throw 'Full source inventory hash mismatch.' }
foreach ($property in $index.pinnedOriginalByteSha256.psobject.Properties) { if (-not $mapped.ContainsKey($property.Name) -or $mapped[$property.Name].sha256 -cne $property.Value) { throw 'Original control pin mismatch.' } }
[pscustomobject]@{method='.NET exact raw byte restoration';target=$targetRoot;files=$seen.Count;originalBytes=$totalBytes;sourceInventorySha256=$inventorySha;allPacketHashesVerified=$true;allScopedPublicSourceFilesComparedByteForByte=$true;identityHashVerified=$true;packetLimitBytes=2097151;noSourceOrRepositoryWrite=$true} | ConvertTo-Json -Depth 4
